command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/public-source-delivery-policy-20261006"
$candidate="e495b29c89fa538363ecd8bbea9a788c81ca743e"
$baseline="8b3ff0da418f8d9c154f0984921359f4a620b552"
$temp=Join-Path $env:RUNNER_TEMP ("public-source-policy-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate/tag fetch failed"}
  $mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
  $branchSha=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($mainSha -ne $baseline){throw "main moved before public-source validation: $mainSha"}
  if($branchSha -ne $candidate){throw "candidate moved before public-source validation: $branchSha"}

  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check $baseline $candidate
  if($LASTEXITCODE -ne 0){throw "git diff --check failed"}

  & python -X utf8 tools\winui\check_python_static.py packaging\public_source_delivery.py tests\winui\test_public_source_delivery_contract.py
  if($LASTEXITCODE -ne 0){throw "public source policy static check failed"}

  & python -X utf8 -m unittest tests.winui.test_public_source_delivery_contract tests.winui.test_release_source_bundle_contract tests.winui.test_release_payload_contract tests.winui.test_installer_contract
  if($LASTEXITCODE -ne 0){throw "public source/release package contracts failed"}

  & python -X utf8 packaging\public_source_delivery.py --phase prepublish
  if($LASTEXITCODE -ne 0){throw "public source prepublication policy check failed"}

  & cmd /c test.bat policy
  if($LASTEXITCODE -ne 0){throw "policy validation failed"}

  $immutable=& gh api repos/tngkrwlsmd/flyExplorer/immutable-releases
  if($LASTEXITCODE -ne 0){throw "immutable release status query failed"}
  $immutableObject=$immutable | ConvertFrom-Json
  if(-not $immutableObject.enabled){throw "immutable releases are not enabled"}

  & git show-ref --verify --quiet refs/tags/v1.0.0.0
  if($LASTEXITCODE -eq 0){throw "reserved release tag was pre-created and remains mutable"}
  $global:LASTEXITCODE=0

  $policy=Get-Content -Raw -Encoding UTF8 -LiteralPath "packaging\PUBLIC_SOURCE_DELIVERY.json" | ConvertFrom-Json
  if($policy.selected_gplv3_section_6_method -ne "6(d)-network-equivalent-access"){throw "section 6(d) policy mismatch"}
  if($policy.retention_policy.minimum_days_after_last_public_binary_availability -lt 1095){throw "retention policy is too short"}
  if($policy.designated_public_place.authentication_required){throw "public source policy requires authentication"}
  if($policy.designated_public_place.source_additional_charge){throw "public source policy charges for source"}

  Write-Host "IMMUTABLE_RELEASES_ENABLED=true"
  Write-Host "RESERVED_RELEASE_TAG=v1.0.0.0"
  Write-Host "RESERVED_RELEASE_TAG_PRECREATED=false"
  Write-Host "GPLV3_SECTION6_METHOD=6(d)-network-equivalent-access"
  Write-Host "SOURCE_RETENTION_AFTER_WITHDRAWAL_DAYS=1095"
  Write-Host "PUBLIC_SOURCE_DELIVERY_POLICY_VALIDATION=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
